ValidationRule.errorConditionFormula:
AND(
OR(
ISNEW() ,
ISCHANGED( NSP_Forecast_Status__c )
) ,
OR(
AND(
NOT( $Permission.Opportunity_Closed_Won_NCS_User ) ,
OR(
ISPICKVAL( NSP_Forecast_Status__c , 'Pending-Docs Submitted to NCS' ) ,
ISPICKVAL( NSP_Forecast_Status__c , 'Sold-Booked' )
)
) ,
AND(
NOT(
OR(
$Permission.Opportunity_Forecast_Category_Edit_Allowed ,
$Profile.Name = 'Sales Manager'
)
) ,
ISPICKVAL( NSP_Forecast_Status__c , 'Verbal-Appt Set to Pickup Docs' )
)
)
)
